INSERT INTO "outreach_messages" ("id","campaign_id","prospect_id","sequence_step","type","subject","body","status","provider_message_id","delivered_at","opened_at","clicked_at","replied_at","created_at","sent_at") VALUES('9b5a1cf2-a393-4f36-b2b8-9031124a6233','87040095-5bc8-4c8d-be7c-13c134d62441','28dc8078-858b-48ca-af5d-b947b8c2d9a4',2,'followup_2','A note from precious',replace('I came across your business earlier \nand spent a little time looking through your website.\n\nOne thing caught my attention: the offer itself is clear, \nbut the path from understanding what you do to actually \ntaking the next step could be much stronger.\n\nThere are a few places where potential customers \nmay be dropping off before they contact you.\n\nI work on finding these kinds of conversion leaks \nand figuring out what is causing them.\n\nI thought I''d reach out because I noticed a couple \nof things that may be worth looking at on your site.\n\nWould you be open to me sending over what I found?','\n',char(10)),'sent','1a10cf2d13cb70b5',NULL,NULL,NULL,NULL,'2026-10-05T16:43:20.214Z','2026-10-05T16:43:22.500Z');
INSERT INTO "outreach_messages" ("id","campaign_id","prospect_id","sequence_step","type","subject","body","status","provider_message_id","delivered_at","opened_at","clicked_at","replied_at","created_at","sent_at") VALUES('de8c4170-8d59-497e-b982-cf45ddcd675c','87040095-5bc8-4c8d-be7c-13c134d62441','28dc8078-858b-48ca-af5d-b947b8c2d9a4',3,'followup_3','Hi Precious',replace('I noticed something about your website that might be costing you conversions.\n\nWould you be interested in hearing what I found?','\n',char(10)),'sent','1a10d9ba5e6d3b37',NULL,NULL,NULL,NULL,'2026-10-05T19:47:45.877Z','2026-10-05T19:47:46.672Z');
