INSERT INTO "outreach_messages" ("id","campaign_id","prospect_id","sequence_step","type","subject","body","status","provider_message_id","delivered_at","opened_at","clicked_at","replied_at","created_at","sent_at") VALUES('6d323a1e-37af-44e8-931d-e5e5ff066ded','87040095-5bc8-4c8d-be7c-13c134d62441','28dc8078-858b-48ca-af5d-b947b8c2d9a4',5,'followup_5','Hi Precious',replace('I noticed something about your website that might be costing you conversions.\n\nWould you be interested in hearing what I found?','\n',char(10)),'sent','1a10db8f75b3f6fa',NULL,NULL,NULL,NULL,'2026-10-05T20:19:46.240Z','2026-10-05T20:19:48.614Z');
INSERT INTO "outreach_messages" ("id","campaign_id","prospect_id","sequence_step","type","subject","body","status","provider_message_id","delivered_at","opened_at","clicked_at","replied_at","created_at","sent_at") VALUES('bfb1b9da-6a4d-450f-9039-97ce862ea4ad','87040095-5bc8-4c8d-be7c-13c134d62441','ed3271ff-c9ad-4ee9-ae5d-c74baf61c419',0,'initial','Hi Elijah','not funny. didnt laugh. not even a single giggle. not a single haha. not even a hehe. not a sound. not at all funny. i did not even feel like laughing one bit. i didn’t let out even a chuckle. not even a subtle burst of air out of my esophagus.','sent','1a10e1f20751cf65',NULL,NULL,NULL,NULL,'2026-10-05T22:11:21.565Z','2026-10-05T22:11:24.088Z');
INSERT INTO "outreach_messages" ("id","campaign_id","prospect_id","sequence_step","type","subject","body","status","provider_message_id","delivered_at","opened_at","clicked_at","replied_at","created_at","sent_at") VALUES('cc61c632-7988-49b8-890c-2626ebed5a6a','87040095-5bc8-4c8d-be7c-13c134d62441','ed3271ff-c9ad-4ee9-ae5d-c74baf61c419',1,'followup_1','check this out precious',replace('Hi Precious,\n\nYou might not have noticed this yet, but something important just shifted.\n\nA lot of product discovery isn’t happening on Google anymore.\n\nIt’s happening inside AI tools.\n\nPeople are asking things like:\n“How do I cook perfect jollof rice?”\n“What spice mix should I use?”\n\nAnd instead of showing websites…\n\nAI tools choose which brands to mention.\n\nRight now, most stores aren’t positioned for this at all.\n\nWhich means early movers are quietly taking that visibility.\n\nI’ve been helping a few brands set this up properly.\n\nFrom what I saw on your store, there’s a clear opportunity here.\n\nCurious if you’ve looked into this yet.','\n',char(10)),'sent','1a1246e113a95b9c',NULL,NULL,NULL,NULL,'2026-10-10T06:09:14.865Z','2026-10-10T06:09:15.625Z');
INSERT INTO "outreach_messages" ("id","campaign_id","prospect_id","sequence_step","type","subject","body","status","provider_message_id","delivered_at","opened_at","clicked_at","replied_at","created_at","sent_at") VALUES('0251bcd6-d2b0-4283-b493-6ac9c8f22aa9','87040095-5bc8-4c8d-be7c-13c134d62441','1a0e244f-5ec4-4cc5-b8df-9d2060e0fa2e',0,'initial','Hey Supeerior',replace('I respect your inbox but had to share this with\nyou…  so I’ll keep this quick\n\nI just checked out your store,  Cooking Plumber  — and honestly,\nyou’re doing such an amazing job with your\nbrand 👏.\n\n\nBut here’s the thing. While your site looks good,\nI notice a couple of areas that might be quietly\nleaking profits and holding back your growth.\n\n\nAnd you know how it goes — even the tiniest\nleaks can add up. But the good news is fixing\nthem usually adds serious extra revenue…\nwithout you having to spend excessively on ads\nor traffic.\n\nFor example, one store I worked on recently\nwas losing about 20% of her sales because of\njust a few content and technical issues. I fixed\nthose leaks, and thousands started flowing back\ninto her monthly revenue. And honestly, I keep\nspotting the same patterns again and again on\nother eCommerce sites.\n\n\nYou see, I''ve been digging into this, and I found\nsome pretty powerful insight which made me\ncreate a Ultimate Support System — because I\ngot tired of seeing stores piece everything together\nrandomly (a freelancer here, a tool there, an ad\ncampaign somewhere else) with no connection.\nMy system pulls it all together — SEO, content,\ncopy, email, social, and even tech fixes — so\neverything works in sync instead of pulling in\ndifferent directions.\n\n\nAnd when you do that, a few things happen:\n\nYou stop the hidden leaks 💧\n\nYou boost your conversions 📈\n\nYou multiply your growth instead of wasting effort ⚡\n\nAnd here’s the catch — every month those\nleaks keep running, they quietly drain your\nprofit. You might not see it, but it’s happening.\nFixing them sooner just means you stop the\nleaks immediately.\n\n\n👉 That’s why I’d love to send you my PDF.\nIt’s a simple overview — you can check it out,\njust few mins to read and see if it makes sense\nfor you right now.\n\n\nWould you like me to send it over?','\n',char(10)),'sent','1a12b1e37a441b3d',NULL,NULL,NULL,NULL,'2026-10-11T13:19:22.055Z','2026-10-11T13:19:22.934Z');
