PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE clients (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    business TEXT,
    website TEXT,
    token_hash TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE conversations (
    id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    subject TEXT NOT NULL DEFAULT 'Leak Hunt Investigation',
    status TEXT NOT NULL DEFAULT 'open',
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (client_id)
        REFERENCES clients(id)
        ON DELETE CASCADE
);
CREATE TABLE messages (
    id TEXT PRIMARY KEY,
    conversation_id TEXT NOT NULL,
    sender_type TEXT NOT NULL,
    message TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (conversation_id)
        REFERENCES conversations(id)
        ON DELETE CASCADE
);
CREATE TABLE sessions (
    id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (client_id)
        REFERENCES clients(id)
        ON DELETE CASCADE
);
CREATE TABLE reviews (
    id TEXT PRIMARY KEY,
    client_id TEXT,
    name TEXT NOT NULL,
    business TEXT,
    rating INTEGER,
    review TEXT NOT NULL,
    approved INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (client_id)
        REFERENCES clients(id)
        ON DELETE SET NULL
);
CREATE TABLE blog_comments (
    id TEXT PRIMARY KEY,
    article_slug TEXT NOT NULL,
    name TEXT NOT NULL,
    email TEXT,
    comment TEXT NOT NULL,
    approved INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE notifications (
    id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    type TEXT NOT NULL,
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    read INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (client_id)
        REFERENCES clients(id)
        ON DELETE CASCADE
);
CREATE TABLE admin_sessions (
    id TEXT PRIMARY KEY,
    expires_at TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE files (
    id TEXT PRIMARY KEY,

    client_id TEXT NOT NULL,

    conversation_id TEXT NOT NULL,

    message_id TEXT,

    original_name TEXT NOT NULL,

    storage_key TEXT NOT NULL UNIQUE,

    content_type TEXT NOT NULL,

    file_size INTEGER NOT NULL,

    uploaded_by TEXT NOT NULL,

    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (client_id)
        REFERENCES clients(id)
        ON DELETE CASCADE,

    FOREIGN KEY (conversation_id)
        REFERENCES conversations(id)
        ON DELETE CASCADE,

    FOREIGN KEY (message_id)
        REFERENCES messages(id)
        ON DELETE SET NULL
);
CREATE TABLE attachments (
    id TEXT PRIMARY KEY,
    message_id TEXT NOT NULL,
    conversation_id TEXT NOT NULL,
    client_id TEXT NOT NULL,
    original_name TEXT NOT NULL,
    stored_name TEXT NOT NULL,
    content_type TEXT NOT NULL,
    size INTEGER NOT NULL,
    r2_key TEXT NOT NULL UNIQUE,
    uploaded_by TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (message_id)
        REFERENCES messages(id)
        ON DELETE CASCADE,

    FOREIGN KEY (conversation_id)
        REFERENCES conversations(id)
        ON DELETE CASCADE,

    FOREIGN KEY (client_id)
        REFERENCES clients(id)
        ON DELETE CASCADE
);
CREATE TABLE analytics_visitors (
    visitor_id TEXT PRIMARY KEY,
    first_seen_at TEXT NOT NULL,
    last_seen_at TEXT NOT NULL,
    first_referrer TEXT,
    first_landing_page TEXT,
    last_page TEXT,
    session_count INTEGER NOT NULL DEFAULT 0,
    event_count INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE analytics_sessions (
    session_id TEXT PRIMARY KEY,
    visitor_id TEXT NOT NULL,
    started_at TEXT NOT NULL,
    last_seen_at TEXT NOT NULL,
    landing_page TEXT,
    referrer TEXT,
    last_page TEXT,
    event_count INTEGER NOT NULL DEFAULT 0,
    FOREIGN KEY (visitor_id) REFERENCES analytics_visitors(visitor_id) ON DELETE CASCADE
);
CREATE TABLE analytics_events (
    event_id TEXT PRIMARY KEY,
    visitor_id TEXT NOT NULL,
    session_id TEXT NOT NULL,
    event_type TEXT NOT NULL,
    page TEXT,
    referrer TEXT,
    metadata TEXT,
    created_at TEXT NOT NULL,
    FOREIGN KEY (visitor_id) REFERENCES analytics_visitors(visitor_id) ON DELETE CASCADE,
    FOREIGN KEY (session_id) REFERENCES analytics_sessions(session_id) ON DELETE CASCADE
);
CREATE TABLE analytics_v2_sessions (
 session_id TEXT PRIMARY KEY, visitor_id TEXT NOT NULL,
 started_at TEXT NOT NULL, last_seen_at TEXT NOT NULL,
 landing_page TEXT NOT NULL, last_page TEXT NOT NULL,
 source TEXT NOT NULL DEFAULT 'direct', medium TEXT NOT NULL DEFAULT 'none',
 campaign TEXT NOT NULL DEFAULT '', referrer TEXT NOT NULL DEFAULT '',
 device TEXT NOT NULL DEFAULT 'unknown', internal INTEGER NOT NULL DEFAULT 0,
 UNIQUE(session_id, visitor_id)
);
CREATE TABLE analytics_v2_events (
 event_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, visitor_id TEXT NOT NULL,
 event_type TEXT NOT NULL, page TEXT NOT NULL, occurred_at TEXT NOT NULL,
 received_at TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}',
 FOREIGN KEY(session_id, visitor_id) REFERENCES analytics_v2_sessions(session_id, visitor_id) ON DELETE CASCADE
);
CREATE TABLE analytics_v2_leads (
 lead_id TEXT PRIMARY KEY REFERENCES clients(id) ON DELETE CASCADE,
 session_id TEXT, visitor_id TEXT, form_id TEXT NOT NULL DEFAULT '', attempt_id TEXT NOT NULL DEFAULT '',
 created_at TEXT NOT NULL, stage TEXT NOT NULL DEFAULT 'enquiry'
 CHECK(stage IN ('enquiry','qualified','proposal','won','lost')),
 updated_at TEXT NOT NULL,
 FOREIGN KEY(session_id, visitor_id) REFERENCES analytics_v2_sessions(session_id, visitor_id) ON DELETE SET NULL
);
CREATE TABLE analytics_v2_rate_limits (
 bucket TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL
);
CREATE TABLE client_service_interests (
    id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    service_id TEXT NOT NULL,
    service_slug TEXT NOT NULL,
    service_title TEXT NOT NULL,
    service_number TEXT,
    service_category TEXT,
    service_type TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (client_id)
        REFERENCES clients(id)
        ON DELETE CASCADE,

    UNIQUE(client_id, service_id)
);
CREATE TABLE email_notifications (
    id TEXT PRIMARY KEY,
    conversation_id TEXT NOT NULL,
    client_id TEXT NOT NULL,
    type TEXT NOT NULL CHECK (type IN ('reply', 'welcome', 'custom')),
    recipient_email TEXT NOT NULL,
    subject TEXT NOT NULL,
    custom_message TEXT,
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'sent', 'failed')),
    provider_message_id TEXT,
    error_message TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    sent_at TEXT,
    FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
    FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE
);
CREATE TABLE outreach_campaigns (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT DEFAULT '',
  status TEXT NOT NULL DEFAULT 'active',
  start_date TEXT NOT NULL,
  daily_limit INTEGER NOT NULL DEFAULT 15,
  max_prospects INTEGER NOT NULL DEFAULT 60,
  followup_intervals TEXT NOT NULL DEFAULT '[3,4,5,7,10]',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE outreach_prospects (
  id TEXT PRIMARY KEY,
  campaign_id TEXT NOT NULL,
  sequence_no INTEGER NOT NULL,
  name TEXT DEFAULT '', email TEXT NOT NULL UNIQUE, website TEXT DEFAULT '', company TEXT DEFAULT '', role TEXT DEFAULT '',
  observation TEXT DEFAULT '', notes TEXT DEFAULT '',
  email_health TEXT NOT NULL DEFAULT 'mail_ready', email_health_reason TEXT DEFAULT '', email_checked_at TEXT,
  research_ready INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'scheduled', initial_due_date TEXT NOT NULL,
  last_sent_at TEXT, followup_step INTEGER NOT NULL DEFAULT 0, next_followup_date TEXT,
  sequence_complete INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
  FOREIGN KEY (campaign_id) REFERENCES outreach_campaigns(id)
);
CREATE TABLE outreach_messages (
  id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL, prospect_id TEXT NOT NULL,
  sequence_step INTEGER NOT NULL, type TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'recorded', provider_message_id TEXT,
  delivered_at TEXT, opened_at TEXT, clicked_at TEXT, replied_at TEXT,
  created_at TEXT NOT NULL, sent_at TEXT,
  FOREIGN KEY (campaign_id) REFERENCES outreach_campaigns(id), FOREIGN KEY (prospect_id) REFERENCES outreach_prospects(id)
);
CREATE TABLE outreach_events (
  id TEXT PRIMARY KEY, campaign_id TEXT, prospect_id TEXT, type TEXT NOT NULL, detail TEXT DEFAULT '', created_at TEXT NOT NULL
);
CREATE TABLE outreach_templates (
  id TEXT PRIMARY KEY, sequence_step INTEGER NOT NULL UNIQUE, name TEXT NOT NULL, subject TEXT DEFAULT '', body TEXT DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE outreach_suppressions (
  email TEXT PRIMARY KEY, reason TEXT DEFAULT '', source TEXT DEFAULT 'admin', created_at TEXT NOT NULL
);
CREATE TABLE outreach_google_connection (
  id TEXT PRIMARY KEY,
  sender_email TEXT NOT NULL,
  refresh_token_encrypted TEXT NOT NULL,
  scope TEXT NOT NULL,
  connected_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE outreach_oauth_states (
  state TEXT PRIMARY KEY,
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL
);
CREATE INDEX idx_conversations_client
ON conversations(client_id);
CREATE INDEX idx_messages_conversation
ON messages(conversation_id);
CREATE INDEX idx_sessions_client
ON sessions(client_id);
CREATE INDEX idx_comments_article
ON blog_comments(article_slug);
CREATE INDEX idx_notifications_client
ON notifications(client_id);
CREATE INDEX idx_admin_sessions_expires
ON admin_sessions(expires_at);
CREATE INDEX idx_files_client
ON files(client_id);
CREATE INDEX idx_files_conversation
ON files(conversation_id);
CREATE INDEX idx_files_message
ON files(message_id);
CREATE INDEX idx_attachments_message
ON attachments(message_id);
CREATE INDEX idx_attachments_conversation
ON attachments(conversation_id);
CREATE INDEX idx_attachments_client
ON attachments(client_id);
CREATE INDEX idx_analytics_events_created_at
ON analytics_events(created_at DESC);
CREATE INDEX idx_analytics_events_visitor
ON analytics_events(visitor_id, created_at DESC);
CREATE INDEX idx_analytics_events_session
ON analytics_events(session_id, created_at ASC);
CREATE INDEX idx_analytics_events_type
ON analytics_events(event_type, created_at DESC);
CREATE INDEX idx_analytics_sessions_visitor
ON analytics_sessions(visitor_id, started_at DESC);
CREATE INDEX av2_sessions_start ON analytics_v2_sessions(started_at, internal);
CREATE INDEX av2_sessions_visitor ON analytics_v2_sessions(visitor_id, started_at);
CREATE INDEX av2_events_session ON analytics_v2_events(session_id, occurred_at, event_id);
CREATE INDEX av2_events_received ON analytics_v2_events(received_at);
CREATE INDEX av2_leads_session ON analytics_v2_leads(session_id, created_at);
CREATE INDEX av2_leads_created ON analytics_v2_leads(created_at);
CREATE INDEX av2_rate_expiry ON analytics_v2_rate_limits(expires_at);
CREATE INDEX idx_client_service_interests_client
ON client_service_interests(client_id);
CREATE INDEX idx_client_service_interests_slug
ON client_service_interests(service_slug);
CREATE INDEX idx_email_notifications_conversation
ON email_notifications (conversation_id, created_at DESC);
CREATE INDEX idx_email_notifications_client
ON email_notifications (client_id, created_at DESC);
CREATE INDEX idx_outreach_prospects_campaign ON outreach_prospects(campaign_id, sequence_no);
CREATE INDEX idx_outreach_prospects_due ON outreach_prospects(initial_due_date, next_followup_date, status);
CREATE INDEX idx_outreach_messages_prospect ON outreach_messages(prospect_id, created_at);
CREATE INDEX idx_outreach_events_created ON outreach_events(created_at DESC);
CREATE INDEX idx_outreach_oauth_states_expiry
ON outreach_oauth_states(expires_at);
CREATE TRIGGER av2_event_updates_session AFTER INSERT ON analytics_v2_events
BEGIN
 UPDATE analytics_v2_sessions SET
  landing_page = CASE WHEN NEW.occurred_at < started_at THEN NEW.page ELSE landing_page END,
  last_page = CASE WHEN NEW.occurred_at >= last_seen_at THEN NEW.page ELSE last_page END,
  started_at = MIN(started_at, NEW.occurred_at),
  last_seen_at = MAX(last_seen_at, NEW.occurred_at)
 WHERE session_id = NEW.session_id;
END;
CREATE TRIGGER av2_event_identity_guard BEFORE INSERT ON analytics_v2_events
WHEN EXISTS (SELECT 1 FROM analytics_v2_events WHERE event_id=NEW.event_id AND (session_id!=NEW.session_id OR visitor_id!=NEW.visitor_id))
BEGIN
 SELECT RAISE(ABORT, 'analytics event identity constraint');
END;
